package de.example.reports.command;
import de.example.reports.ReportsPlugin; import de.example.reports.database.Database; import de.example.reports.gui.AdminReportGuiService; import de.example.reports.model.*; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class ReportsCommand implements CommandExecutor {private final ReportsPlugin plugin;private final Database db;private final AdminReportGuiService gui;public ReportsCommand(ReportsPlugin p,Database d,AdminReportGuiService g){plugin=p;db=d;gui=g;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(a.length==0&&s instanceof Player player){if(!s.hasPermission("reports.agui")){plugin.messages().send(s,"no-permission");return true;}gui.open(player);return true;}if(!s.hasPermission("reports.view")){plugin.messages().send(s,"no-permission");return true;}if(a.length==1&&a[0].equalsIgnoreCase("reload")){if(!s.hasPermission("reports.admin")){plugin.messages().send(s,"no-permission");return true;}plugin.reloadPlugin();s.sendMessage("Reports configuration reloaded.");return true;}if(a.length>=2&&a[0].equalsIgnoreCase("info")){try{long id=Long.parseLong(a[1]);db.report(id).thenAccept(o->plugin.getServer().getScheduler().runTask(plugin,()->{if(o.isEmpty()){s.sendMessage("Report #"+id+" not found.");return;}Report r=o.get();s.sendMessage("#"+r.id()+" | "+r.status()+" | "+r.reportedName()+" reported by "+r.reporterName()+" | "+r.reason());}));}catch(NumberFormatException e){s.sendMessage("Usage: /reports info <id>");}return true;}if(a.length>=3&&a[0].equalsIgnoreCase("status")){if(!s.hasPermission("reports.manage")){plugin.messages().send(s,"no-permission");return true;}try{long id=Long.parseLong(a[1]);ReportStatus status=ReportStatus.valueOf(a[2].toUpperCase(Locale.ROOT));db.updateStatus(id,status).thenAccept(ok->plugin.getServer().getScheduler().runTask(plugin,()->s.sendMessage(ok?"Report #"+id+" updated to "+status+".":"Report not found.")));}catch(IllegalArgumentException e){s.sendMessage("Usage: /reports status <id> <OPEN|REVIEWING|RESOLVED|REJECTED>");}return true;}s.sendMessage("/reports öffnet die Verwaltung, /reports info <id>, /reports status <id> <status>, /reports reload");return true;}}
